    # Select a uniform divider that separates two nonempty panels.
    candidates = []
    for r, row in enumerate(grid):
        if r and r < h - 1 and row[0] != 0 and all(x == row[0] for x in row):
            candidates.append(("row", r, row[0]))
    for c in range(w):
        if c and c < w - 1 and grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.append(("col", c, grid[0][c]))

    # Divider colors in these puzzles are solid and distinct from the
    # patterned panels; prefer the line whose color occurs least elsewhere.
    if candidates:
        def score(item):
            axis, k, color = item
            count = sum(v == color for row in grid for v in row)
            return count
        axis, k, _ = min(candidates, key=score)
        if axis == "row":
            n = min(k, h-k-1)
            return [[2 if grid[k-1-i][j] != 0 and grid[k+1+i][j] != 0 else 0
                     for j in range(w)] for i in range(n)]
        n = min(k, w-k-1)
        return [[2 if grid[i][k-1-j] != 0 and grid[i][k+1+j] != 0 else 0
                 for j in range(n)] for i in range(h)]
